#include "studio.h"

namespace {
Model crate{};
Texture2D bark{};
}  // namespace

void loadProps() {
  crate = studio::assetModel("models/crate.glb");
  Image image = GenImagePerlinNoise(256, 256, 0, 0, 4.0f);
  bark = LoadTextureFromImage(image);
  UnloadImage(image);
  GenTextureMipmaps(&bark);
  SetTextureFilter(bark, TEXTURE_FILTER_TRILINEAR);
}

void drawProps() {
  studio::tag("crate");
  studio::drawModel(crate, {2.0f, 0.0f, 1.0f}, 1.0f, WHITE);
}
